script:
@import url('https://fonts.googleapis.com/css2?family=Crimson+Pro:ital,wght@0,400;0,500;0,600;1,400;1,500&display=swap');

html { scroll-behavior: smooth; }
::selection { background: #161512; color: #FAFAF6; }

html.gb-js .gb-rise { opacity: 0; transform: translateY(18px); }
html.gb-js .gb-rise.gb-in {
  opacity: 1; transform: none;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}
html.gb-js .gb-d2.gb-in { transition-delay: 0.08s; }
html.gb-js .gb-d3.gb-in { transition-delay: 0.16s; }

.gb-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1px;
  transition: background-size 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.gb-ul:hover { background-size: 100% 1px; }
.gb-btn { transition: opacity 0.2s ease; }
.gb-btn:hover { opacity: 0.82; }
.gb-row { transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1); }
.gb-row:hover { transform: translateX(6px); }
.gb-card { transition: box-shadow 0.35s ease, transform 0.35s ease; }
.gb-card:hover { box-shadow: 5px 5px 0 #E0DED5; transform: translate(-2px, -2px); }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .gb-row, .gb-card, .gb-btn { transition: none; }
}
